window.CODE = Object.assign(window.CODE || {}, {"ch29/demo_roundtrip.py":"\"\"\"Sender and receiver talking to each other, in one process (no network, no keys).\n\n    OFFLINE=1 python demo_roundtrip.py\n\nShows the three things that matter: a good event is processed, a retry of the SAME event is ignored,\nand a forged event is refused.\n\"\"\"\nimport os\n\nos.environ.setdefault(\"OFFLINE\", \"1\")\n\nfrom inbound_webhook import SECRET, app\nfrom outbound import send_event\n\n\n\ndef main():\n    from fastapi.testclient import TestClient\n    tc = TestClient(app)                                          # behaves like httpx.Client, talking straight to the app\n    url = \"http://testserver/events/patient-message\"\n    event = {\"message\": \"What are Dr Rao's clinic days?\", \"channel\": \"whatsapp\"}\n\n    print(\"1. signed event      ->\", send_event(url, event, SECRET, client=tc)[\"reply\"][:60], \"...\")\n    try:\n        send_event(url, event, \"wrong-secret\", retries=1, client=tc)\n    except Exception as e:                                        # the test client raises its own HTTPStatusError type\n        print(\"2. forged signature  ->\", e.response.status_code, e.response.json()[\"detail\"])\n\n    import webhook_security as ws\n    raw, headers = ws.make_headers(SECRET, event, \"same-key-twice\")\n    first = tc.post(url, content=raw, headers=headers).json()[\"status\"]\n    again = tc.post(url, content=raw, headers=headers).json()[\"status\"]\n    print(\"3. same key twice    ->\", first, \"then\", again)\n\n\nif __name__ == \"__main__\":\n    main()\n","ch29/inbound_webhook.py":"\"\"\"Receive events from Zapier, Make or n8n and hand them to the Chapter 27 helpdesk, safely.\n\n    Zap / scenario:  'New message in the patient portal'  ->  POST /events/patient-message  ->  agent  ->  JSON reply\n\nTwo ways in, because the platforms differ:\n  * X-Signature + X-Timestamp  : HMAC-signed (use this wherever the sender can compute it: a code step, Make's functions)\n  * X-Webhook-Token            : a shared secret in a header (what a plain 'send a webhook' action can do)\n\nRun:  OFFLINE=1 WEBHOOK_SECRET=change-me uvicorn inbound_webhook:app --port 8002\n\"\"\"\nimport json\nimport os\nimport sys\nfrom pathlib import Path\n\nfrom fastapi import FastAPI, Header, HTTPException, Request\nfrom pydantic import BaseModel, Field, ValidationError\n\nimport webhook_security as ws\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent / \"ch27\"))\nif os.getenv(\"OFFLINE\") == \"1\":\n    import fake_models\n    fake_models.install()\nimport helpdesk  # noqa: E402  (Chapter 27)\n\nSECRET = os.getenv(\"WEBHOOK_SECRET\", \"change-me\")\napp = FastAPI(title=\"Inbound events\")\nseen = ws.Seen(os.getenv(\"SEEN_DB\", \":memory:\"))\n\n\nclass PatientMessage(BaseModel):\n    message: str = Field(min_length=1, max_length=1000)\n    channel: str = Field(default=\"portal\", pattern=\"^(portal|whatsapp|email)$\")\n\n\n@app.post(\"/events/patient-message\")\nasync def patient_message(request: Request, x_signature: str = Header(default=\"\"), x_timestamp: str = Header(default=\"\"),\n                          x_webhook_token: str = Header(default=\"\"), idempotency_key: str = Header(default=\"\")):\n    raw = await request.body()\n    try:                                                         # 1 + 2: authentic and fresh\n        if x_signature:\n            ws.verify(SECRET, x_timestamp, x_signature, raw)\n        else:\n            ws.verify_token(SECRET, x_webhook_token)\n    except ValueError as e:\n        raise HTTPException(status_code=401, detail=str(e)) from None\n    try:                                                         # 4: valid shape\n        event = PatientMessage.model_validate(json.loads(raw))\n    except (ValidationError, ValueError) as e:\n        raise HTTPException(status_code=422, detail=\"invalid payload\") from e\n    if not idempotency_key:\n        raise HTTPException(status_code=400, detail=\"Idempotency-Key header is required\")\n    if not seen.first_time(idempotency_key):                     # 3: once only. A retry gets a harmless 200, not a second run.\n        return {\"status\": \"duplicate-ignored\"}\n    # Unattended automation has NO human at the approval gate: with no approver every booking is declined (the safe default).\n    res = helpdesk.run_helpdesk(event.message, approver=None)\n    return {\"status\": \"done\", \"reply\": res.reply, \"flags\": res.flags, \"needs_staff\": \"booking-declined\" in res.flags}\n","ch29/outbound.py":"\"\"\"Call a Zapier or Make webhook from your own Python agent: signed, with a timeout, an idempotency key and retries.\n\nTypical use: your agent finishes a task, then triggers a Zap / scenario that writes a row, sends a Slack message or\ncreates a ticket. The agent does the thinking; the automation platform does the plumbing.\n\"\"\"\nimport time\nimport uuid\n\nimport httpx\n\nimport webhook_security as ws\n\n\ndef send_event(url: str, payload: dict, secret: str, *, retries: int = 3, timeout: float = 10, client: httpx.Client | None = None) -> dict:\n    \"\"\"POST `payload` safely. The SAME idempotency key is reused on every retry, so a retry cannot create a duplicate.\"\"\"\n    key = str(uuid.uuid4())\n    client = client or httpx.Client(timeout=timeout)\n    last = None\n    for attempt in range(retries):\n        raw, headers = ws.make_headers(secret, payload, key)          # fresh timestamp and signature each attempt\n        try:\n            r = client.post(url, content=raw, headers=headers)\n            if r.status_code < 500 and r.status_code != 429:\n                r.raise_for_status()                                  # 4xx = our mistake: do NOT retry\n                return r.json()\n            last = f\"HTTP {r.status_code}\"                           # 5xx / 429 = their problem: retry\n        except httpx.TransportError as e:\n            last = type(e).__name__\n        time.sleep(min(2 ** attempt * 0.2, 2))                        # a short, growing pause (use jitter in production)\n    raise RuntimeError(f\"webhook failed after {retries} attempts: {last}\")\n","ch29/test_webhooks.py":"\"\"\"Run:  OFFLINE=1 pytest -q\"\"\"\nimport os\n\nos.environ.setdefault(\"OFFLINE\", \"1\")\nimport httpx  # noqa: E402\nimport pytest  # noqa: E402\nimport webhook_security as ws  # noqa: E402\nfrom fastapi.testclient import TestClient  # noqa: E402\nfrom inbound_webhook import SECRET, app  # noqa: E402\nfrom outbound import send_event  # noqa: E402\n\nclient = TestClient(app)\nBODY = {\"message\": \"Why is there an ECG charge on BILL-2291?\", \"channel\": \"portal\"}\n\n\ndef signed(body=BODY, key=\"k1\", secret=SECRET, now=None):\n    raw, headers = ws.make_headers(secret, body, key, now)\n    return {\"content\": raw, \"headers\": headers}\n\n\ndef test_signature_roundtrip_and_tamper():\n    raw, h = ws.make_headers(\"s\", {\"a\": 1}, \"k\")\n    ws.verify(\"s\", h[\"X-Timestamp\"], h[\"X-Signature\"], raw)\n    with pytest.raises(ValueError):\n        ws.verify(\"s\", h[\"X-Timestamp\"], h[\"X-Signature\"], raw + b\" \")           # body changed\n    with pytest.raises(ValueError):\n        ws.verify(\"other\", h[\"X-Timestamp\"], h[\"X-Signature\"], raw)              # wrong secret\n\n\ndef test_old_messages_are_rejected_as_replays():\n    raw, h = ws.make_headers(\"s\", {\"a\": 1}, \"k\", now=1_000_000)\n    with pytest.raises(ValueError, match=\"window\"):\n        ws.verify(\"s\", h[\"X-Timestamp\"], h[\"X-Signature\"], raw, now=1_000_000 + 3600)\n\n\ndef test_signed_event_is_processed():\n    r = client.post(\"/events/patient-message\", **signed(key=\"a1\"))\n    assert r.status_code == 200 and \"350\" in r.json()[\"reply\"]\n\n\ndef test_token_only_senders_work_too():\n    r = client.post(\"/events/patient-message\", json=BODY, headers={\"X-Webhook-Token\": SECRET, \"Idempotency-Key\": \"t1\"})\n    assert r.status_code == 200\n\n\ndef test_wrong_secret_is_refused():\n    assert client.post(\"/events/patient-message\", **signed(secret=\"wrong\", key=\"b1\")).status_code == 401\n    assert client.post(\"/events/patient-message\", json=BODY, headers={\"X-Webhook-Token\": \"nope\", \"Idempotency-Key\": \"b2\"}).status_code == 401\n\n\ndef test_a_retry_is_not_processed_twice():\n    first = client.post(\"/events/patient-message\", **signed(key=\"dup\"))\n    again = client.post(\"/events/patient-message\", **signed(key=\"dup\"))\n    assert first.json()[\"status\"] == \"done\" and again.json()[\"status\"] == \"duplicate-ignored\"\n\n\ndef test_bad_payloads_are_rejected():\n    assert client.post(\"/events/patient-message\", **signed({\"message\": \"\"}, key=\"c1\")).status_code == 422\n    assert client.post(\"/events/patient-message\", **signed({\"message\": \"hi\", \"channel\": \"fax\"}, key=\"c2\")).status_code == 422\n    assert client.post(\"/events/patient-message\", **signed({\"message\": \"hi\", \"extra\": 1}, key=\"c3\")).status_code in (200, 422)\n\n\ndef test_booking_via_automation_is_declined_without_a_human():\n    r = client.post(\"/events/patient-message\", **signed({\"message\": \"I'm Asha Verma. Please book me with Dr Rao on Thursday.\"}, key=\"d1\"))\n    assert r.json()[\"needs_staff\"] is True\n\n\ndef test_sender_retries_with_one_key_and_gives_up_on_4xx(monkeypatch):\n    monkeypatch.setattr(\"outbound.time.sleep\", lambda s: None)\n    calls = []\n\n    def handler(request):\n        calls.append(request.headers[\"idempotency-key\"])\n        return httpx.Response(503) if len(calls) < 3 else httpx.Response(200, json={\"ok\": True})\n    ok = send_event(\"http://x/hook\", {\"a\": 1}, \"s\", client=httpx.Client(transport=httpx.MockTransport(handler)))\n    assert ok == {\"ok\": True} and len(calls) == 3 and len(set(calls)) == 1          # same key on every retry\n    with pytest.raises(httpx.HTTPStatusError):\n        send_event(\"http://x/hook\", {}, \"s\", client=httpx.Client(transport=httpx.MockTransport(lambda r: httpx.Response(400))))\n","ch29/test_zapier_step.py":"import zapier_code_step as z\n\n\ndef test_routes():\n    assert z.run({\"message\": \"My father has chest pain\"})[\"route\"] == \"emergency\"\n    assert z.run({\"message\": \"Need an HIV test\"})[\"route\"] == \"human-only\"\n    assert z.run({\"message\": \"Where is the cardiology OPD?\"})[\"route\"] == \"ai\"\n\n\ndef test_output_is_json_serialisable_and_bounded():\n    import json\n    out = z.run({\"message\": \"x\" * 5000})\n    json.dumps(out)\n    assert out[\"length\"] == 1000\n\n\ndef test_missing_key_does_not_crash():\n    assert z.run({})[\"route\"] == \"ai\"\n","ch29/webhook_security.py":"\"\"\"Safe webhooks, in one small module. Zapier, Make, n8n and your own agents all talk to each other with webhooks,\nand a webhook is a public door. Four checks protect it:\n\n  1. AUTHENTICITY  a shared secret, or better an HMAC signature of the body\n  2. FRESHNESS     a timestamp inside a short window (stops someone replaying an old message)\n  3. ONCE ONLY     an idempotency key (platforms retry; one event must never be processed twice)\n  4. VALID SHAPE   a typed payload (reject anything unexpected before it touches an agent)\n\"\"\"\nimport hashlib\nimport hmac\nimport json\nimport sqlite3\nimport time\n\nTOLERANCE_SECONDS = 300          # accept timestamps up to 5 minutes old (or ahead, for small clock differences)\n\n\ndef sign(secret: str, timestamp: int, body: bytes) -> str:\n    \"\"\"HMAC-SHA256 over 'timestamp.body'. The timestamp is INSIDE the signature, so it cannot be swapped.\"\"\"\n    return hmac.new(secret.encode(), f\"{timestamp}.\".encode() + body, hashlib.sha256).hexdigest()\n\n\ndef verify(secret: str, timestamp: str, signature: str, body: bytes, now: float | None = None) -> None:\n    \"\"\"Raise ValueError unless the message is authentic AND fresh. Constant-time comparison.\"\"\"\n    try:\n        ts = int(timestamp)\n    except (TypeError, ValueError):\n        raise ValueError(\"bad timestamp\") from None\n    if abs((now or time.time()) - ts) > TOLERANCE_SECONDS:\n        raise ValueError(\"timestamp outside the allowed window (possible replay)\")\n    if not hmac.compare_digest(sign(secret, ts, body), signature or \"\"):\n        raise ValueError(\"bad signature\")\n\n\ndef verify_token(expected: str, received: str) -> None:\n    \"\"\"For platforms that can only add a fixed header (e.g. Zapier's Webhooks action): a shared secret token.\"\"\"\n    if not hmac.compare_digest(expected, received or \"\"):\n        raise ValueError(\"bad token\")\n\n\nclass Seen:\n    \"\"\"Remembers idempotency keys. SQLite survives restarts; use your real database or Redis in production.\"\"\"\n\n    def __init__(self, path: str = \":memory:\"):\n        self.db = sqlite3.connect(path, check_same_thread=False)\n        self.db.execute(\"CREATE TABLE IF NOT EXISTS seen (key TEXT PRIMARY KEY, at REAL)\")\n\n    def first_time(self, key: str) -> bool:\n        \"\"\"True the first time a key is seen, False after. The PRIMARY KEY makes this safe even under a race.\"\"\"\n        try:\n            with self.db:\n                self.db.execute(\"INSERT INTO seen VALUES (?, ?)\", (key, time.time()))\n            return True\n        except sqlite3.IntegrityError:\n            return False\n\n\ndef make_headers(secret: str, body: dict, idempotency_key: str, now: int | None = None) -> tuple[bytes, dict]:\n    \"\"\"What a SENDER (your Python agent, or a Zapier Code step) adds to an outgoing webhook.\"\"\"\n    raw = json.dumps(body, separators=(\",\", \":\")).encode()\n    ts = now or int(time.time())\n    return raw, {\"Content-Type\": \"application/json\", \"X-Timestamp\": str(ts), \"X-Signature\": sign(secret, ts, raw),\n                 \"Idempotency-Key\": idempotency_key}\n","ch29/zapier_code_step.py":"\"\"\"A 'Code by Zapier' (Python) step: decide whether a patient message needs a person, BEFORE any AI step runs.\n\nPaste the body of `run()` into the Code field. In Zapier you do NOT write the function wrapper:\n  * the mapped fields arrive in the dict `input_data` (you define them in the 'Input Data' box, one key per field)\n  * you finish by setting ONE variable called `output` (a dict, or a list of dicts, that must be JSON-serialisable)\nOnly the standard library and `requests` are available inside Zapier, so keep it simple.\n\nWhy a code step and not the AI? Rules that must ALWAYS fire (emergencies, privacy words) belong in plain code: it is free,\ninstant and cannot be talked out of it. The AI step later in the Zap handles the open-ended wording.\n\"\"\"\nimport re\n\nEMERGENCY = re.compile(r\"chest pain|can'?t breathe|cannot breathe|unconscious|severe bleeding|stroke|suicid\", re.I)\nSENSITIVE = re.compile(r\"\\b(hiv|abortion|psychiatr\\w*)\\b\", re.I)\n\n\ndef run(input_data: dict) -> dict:\n    text = str(input_data.get(\"message\", \"\"))[:1000]            # never trust the length of what arrives\n    if EMERGENCY.search(text):\n        route = \"emergency\"                                      # a later Path sends the patient to 108 and pages staff\n    elif SENSITIVE.search(text):\n        route = \"human-only\"                                     # skip the AI step entirely\n    else:\n        route = \"ai\"\n    return {\"route\": route, \"message\": text, \"length\": len(text)}\n\n\n# --- in Zapier the last two lines of the step are simply: ---\n#     output = run(input_data)\n# ---------------------------------------------------------------------\nif __name__ == \"__main__\":                                       # lets you test it on your laptop first\n    for m in [\"What time does Dr Mehta see patients?\", \"I have chest pain since morning\", \"Is HIV testing done here?\"]:\n        print(run({\"message\": m}))\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
